// Step 1: Extract execution and error details
const input = $input.first().json;

const execution = input.execution || {};
const workflow = input.workflow || {};
const rawError = execution.error || input.error || {};

// Helper to sanitize secrets from text
function sanitizeText(str) {
  if (!str) return '';
  let s = String(str);
  // Redact Bearer / Basic tokens
  s = s.replace(/Bearer\s+[A-Za-z0-9_\-\.]+/gi, 'Bearer [REDACTED]');
  s = s.replace(/bot[0-9]+:[A-Za-z0-9_\-]+/gi, 'bot[REDACTED_TELEGRAM_TOKEN]');
  s = s.replace(/(password|secret|key|token|encryption_key)=[^&\s]+/gi, '$1=[REDACTED]');
  s = s.replace(/postgres:\/\/[^@]+@/gi, 'postgres://[REDACTED]@');
  return s;
}

const errorMessageRaw = rawError.message || rawError.description || 'Unknown execution failure';
const safeMessage = sanitizeText(errorMessageRaw);
const safeStack = sanitizeText(rawError.stack || '');

// Step 2: Classify operational error
let operationalClass = 'unknown';
let originalCategory = rawError.category || null;

const msgLower = safeMessage.toLowerCase();
if (msgLower.includes('429') || msgLower.includes('rate limit') || msgLower.includes('econnreset') || msgLower.includes('etimedout') || msgLower.includes('timeout') || msgLower.includes('503') || msgLower.includes('502') || msgLower.includes('504')) {
  operationalClass = 'transient';
  if (!originalCategory) originalCategory = 'rate_limit';
} else if (msgLower.includes('401') || msgLower.includes('403') || msgLower.includes('unauthorized') || msgLower.includes('forbidden') || msgLower.includes('jwt')) {
  operationalClass = 'authorization';
  if (!originalCategory) originalCategory = 'authorization';
} else if (msgLower.includes('foreign key') || msgLower.includes('violates') || msgLower.includes('duplicate key') || msgLower.includes('check constraint') || msgLower.includes('integrity')) {
  operationalClass = 'data integrity';
  if (!originalCategory) originalCategory = 'data_integrity';
} else if (msgLower.includes('400') || msgLower.includes('404') || msgLower.includes('not found') || msgLower.includes('validation') || msgLower.includes('invalid')) {
  operationalClass = 'permanent';
  if (!originalCategory) originalCategory = 'validation';
}

// Step 3: Determine if Ingestion ID is present in execution context
let ingestionId = null;
let userId = null;
let correlationId = null;

if (execution.data && execution.data.resultData) {
  const runData = execution.data.resultData.runData || {};
  for (const nodeName of Object.keys(runData)) {
    const nodeRuns = runData[nodeName];
    if (Array.isArray(nodeRuns)) {
      for (const run of nodeRuns) {
        const items = run.data?.main?.[0] || [];
        for (const item of items) {
          if (item.json?.ingestion_id) ingestionId = item.json.ingestion_id;
          if (item.json?.user_id) userId = item.json.user_id;
          if (item.json?.correlation_id) correlationId = item.json.correlation_id;
        }
      }
    }
  }
}

return [{
  json: {
    workflow_id: workflow.id,
    workflow_name: workflow.name,
    execution_id: execution.id,
    operational_class: operationalClass,
    original_category: originalCategory,
    error_code: rawError.code || operationalClass.toUpperCase().replace(/\s+/g, '_'),
    error_message_safe: safeMessage,
    error_stack_safe: safeStack,
    ingestion_id: ingestionId,
    user_id: userId,
    correlation_id: correlationId,
    occurred_at: new Date().toISOString()
  }
}];

const input = $input.first().json;

return [{
  json: {
    ok: true,
    status: 'error_handled',
    operational_class: input.operational_class,
    original_category: input.original_category,
    ingestion_updated: !!input.ingestion_id,
    safe_log: {
      workflow: input.workflow_name,
      execution_id: input.execution_id,
      error_code: input.error_code,
      message: input.error_message_safe,
      occurred_at: input.occurred_at
    }
  }
}];
